	private PropertyMap<object> getPropertyMap(string owner, string propertyName, int propertyType,
			Class<object> saveableClass, bool create)
    {

		try {
			foreach (Field key in registryTable.findRecords(new StringField(owner),
				PROPERTY_OWNER_COL)) {
				DBRecord rec = registryTable.getRecord(key);
				if (propertyName.equals(rec.getString(PROPERTY_NAME_COL))) {
					int type = rec.getIntValue(PROPERTY_TYPE_COL);
					if (propertyType != type) {
						throw new PropertyTypeMismatchException(
							"'" + propertyName + "' is type " + PROPERTY_TYPES[type]);
					}
					if (propertyType == PROPERTY_TYPE_SAVEABLE) {
						string className = rec.getString(PROPERTY_CLASS_COL);
						if (!className.equals(saveableClass.getName())) {
							throw new PropertyTypeMismatchException(
								"'" + propertyName + "' is class " + className);
						}
					}
					return getPropertyMap(rec);
				}
			}

			if (!create) {
				return null;
			}

			long key = registryTable.getKey();
			DBRecord rec = REGISTRY_SCHEMA.createRecord(key);
			rec.setString(PROPERTY_OWNER_COL, owner);
			rec.setString(PROPERTY_NAME_COL, propertyName);
			rec.setIntValue(PROPERTY_TYPE_COL, propertyType);
			if (saveableClass != null) {
				rec.setString(PROPERTY_CLASS_COL, saveableClass.getName());
			}
			PropertyMap<object> map = null;
			bool success = false;
			try {
				map = getPropertyMap(rec);
				registryTable.putRecord(rec);
				if (propertyMapOwners != null) {
					propertyMapOwners.add(owner);
				}
				success = true;
			}
			finally {
				if (!success && map != null) {
					propertyMaps.remove(key);
				}
			}
			return map;

		}
		catch (IOException e) {
			dbError(e);
		}
		return null;
	}

	private PropertyMap<object> getPropertyMap(DBRecord rec)
    {
		try {
			PropertyMap<object> map;
			int type = rec.getIntValue(PROPERTY_TYPE_COL);
			switch (type) {
				case PROPERTY_TYPE_STRING:
					map = new StringPropertyMapDB(dbh, OpenMode.UPGRADE, this, changeMgr,
						addressMap, rec.getString(PROPERTY_NAME_COL), TaskMonitor.DUMMY);
					break;
				case PROPERTY_TYPE_LONG:
					map = new LongPropertyMapDB(dbh, OpenMode.UPGRADE, this, changeMgr, addressMap,
						rec.getString(PROPERTY_NAME_COL), TaskMonitor.DUMMY);
					break;
				case PROPERTY_TYPE_INT:
					map = new IntPropertyMapDB(dbh, OpenMode.UPGRADE, this, changeMgr, addressMap,
						rec.getString(PROPERTY_NAME_COL), TaskMonitor.DUMMY);
					break;
				case PROPERTY_TYPE_BOOLEAN:
					map = new VoidPropertyMapDB(dbh, OpenMode.UPGRADE, this, changeMgr, addressMap,
						rec.getString(PROPERTY_NAME_COL), TaskMonitor.DUMMY);
					break;
				case PROPERTY_TYPE_SAVEABLE:
					string className = rec.getString(PROPERTY_CLASS_COL);
					Class<Saveable> c =
						ObjectPropertyMapDB.getSaveableClassForName(className);
					return new(dbh, OpenMode.UPGRADE, this, changeMgr,
						addressMap, rec.getString(PROPERTY_NAME_COL), c, TaskMonitor.DUMMY, true);
				default:
					throw new IllegalArgumentException("Unsupported property type: " + type);
			}
			propertyMaps.put(rec.getKey(), map);
			return map;
		}
		catch (CancelledException e) {
			throw new AssertException("Unexpected Error", e);
		}
		catch (VersionException e) {
			throw new IOException("Incompatable property data for '" +
				rec.getString(PROPERTY_NAME_COL) + "': " + e.getMessage());
		}
	}

	/* @Override */
	public List<PropertyMap<object>> getProperties(string owner) {
		List<PropertyMap<object>> list = new List<PropertyMap<object>>();
		try {
			foreach (Field key in registryTable.findRecords(new StringField(owner),
				PROPERTY_OWNER_COL)) {
				DBRecord rec = registryTable.getRecord(key);
				list.add(getPropertyMap(rec));
			}
		}
		catch (IOException e) {
			dbError(e);
		}
		return list;
	}

	/* @Override */
	public List<string> getPropertyOwners() {
		if (propertyMapOwners == null) {
			try {
				propertyMapOwners = new HashSet<string>();
				RecordIterator recIter = registryTable.iterator();
				while (recIter.hasNext()) {
					DBRecord rec = recIter.next();
					propertyMapOwners.add(rec.getString(PROPERTY_OWNER_COL));
				}
			}
			catch (IOException e) {
				propertyMapOwners = null;
				dbError(e);
			}
		}
		return new List<string>(propertyMapOwners);
	}

